# Changes the star rating color from grey to gold, matching the
# color used in the Reviews section.
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\components\ProductMeta.tsx"), $bytes)
Write-Host "UPDATED: src\components\ProductMeta.tsx" -ForegroundColor Green
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan